-- =====================================================================
-- NBA Card Tracker — migration 0002 : donnees de reference (seed)
-- FICHIER GENERE AUTOMATIQUEMENT — ne pas editer a la main.
-- Source  : data/2025-26-topps-nba-hoops.json
-- Script  : scripts/generate-seed.mjs  (npm run seed:generate)
-- Genere  : 725 associations joueur/carte
--           -> 675 lignes dans public.cards
--           -> 725 lignes dans public.card_players
-- Relancable sans risque (ON CONFLICT DO UPDATE).
-- =====================================================================

begin;

-- 1. Le set
on conflict (id) do update set
  name = excluded.name,
  manufacturer = excluded.manufacturer,
  release_date = excluded.release_date,
  base_count = excluded.base_count;

-- 2. Les sous-ensembles (12)
on conflict (set_id, id) do update set
  name = excluded.name,
  type = excluded.type;

-- 3. Les cartes (675 numeros uniques)
on conflict (set_id, card_code) do update set
  subset = excluded.subset,
  player = excluded.player,
  team = excluded.team,
  player_id = excluded.player_id,
  team_id = excluded.team_id,
  season = excluded.season,
  rookie = excluded.rookie;
-- variant et jersey_number ne sont volontairement PAS ecrases :
-- ce sont des champs que l'utilisateur peut renseigner lui-meme.

-- 4. Associations carte <-> joueur (725)
on conflict (set_id, card_code, slot) do update set
  player = excluded.player,
  player_id = excluded.player_id,
  team = excluded.team,
  team_id = excluded.team_id,
  season = excluded.season;

commit;
